    mfaEnabled: !!a?.mfaEnabled, authenticatorSetupStarted: !!a?.authenticatorSetupStarted,
    recoveryGenerated: !!a?.recoveryGenerated, recoveryConfirmed: !!a?.recoveryConfirmed
  };
}

